<?php

namespace Database\Seeders;

use App\Models\User;
use Illuminate\Database\Seeder;
use Spatie\Permission\Models\Permission;
use Spatie\Permission\Models\Role;
use Spatie\Permission\PermissionRegistrar;

class ShieldSeeder extends Seeder
{
    /**
     * Available permissions per entity (generated by shield:generate --all).
     * Format: {Action}:{Model} (PascalCase:Pascal, separator ':')
     */
    private const PERMISSIONS = [
        'Appointment'    => ['ViewAny', 'View', 'Create', 'Update', 'Delete', 'DeleteAny'],
        'Doctor'         => ['ViewAny', 'View', 'Create', 'Update', 'Delete', 'DeleteAny'],
        'Invoice'        => ['ViewAny', 'View', 'Create', 'Update', 'Delete', 'DeleteAny'],
        'MedicalRecord'  => ['ViewAny', 'View', 'Create', 'Update', 'Delete', 'DeleteAny'],
        'MedicalService' => ['ViewAny', 'View', 'Create', 'Update', 'Delete', 'DeleteAny'],
        'Patient'        => ['ViewAny', 'View', 'Create', 'Update', 'Delete', 'DeleteAny'],
        'Payment'        => ['ViewAny', 'View', 'Create', 'Update', 'Delete', 'DeleteAny'],
        'Role'           => ['ViewAny', 'View', 'Create', 'Update', 'Delete', 'DeleteAny'],
        'Workspace'      => ['ViewAny', 'View', 'Create', 'Update', 'Delete', 'DeleteAny'],
    ];

    public function run(): void
    {
        // Flush Spatie permission cache before operating.
        app(PermissionRegistrar::class)->forgetCachedPermissions();

        // ------------------------------------------------------------------
        // Ensure every permission in PERMISSIONS exists in the database.
        // This makes the seeder self-contained: it does NOT require that
        // `php artisan shield:generate` has been run beforehand.
        // ------------------------------------------------------------------
        foreach (self::PERMISSIONS as $model => $actions) {
            foreach ($actions as $action) {
                Permission::firstOrCreate([
                    'name'       => "{$action}:{$model}",
                    'guard_name' => 'web',
                ]);
            }
        }

        app(PermissionRegistrar::class)->forgetCachedPermissions();

        $allPermissions = Permission::all()->pluck('name')->toArray();

        // ------------------------------------------------------------------
        // Role: super_admin — unrestricted access (receives all permissions).
        // Gate interception is configured in config/filament-shield.php.
        // ------------------------------------------------------------------
        $superAdmin = Role::firstOrCreate(['name' => 'super_admin', 'guard_name' => 'web']);
        $superAdmin->syncPermissions($allPermissions);

        // ------------------------------------------------------------------
        // Role: admin — full management of clinical data and roles.
        // ------------------------------------------------------------------
        $admin = Role::firstOrCreate(['name' => 'admin', 'guard_name' => 'web']);
        $admin->syncPermissions($allPermissions);

        // ------------------------------------------------------------------
        // Role: doctor — clinical access (patients, appointments, medical records).
        //   - Cannot delete clinical records or manage workspaces/roles.
        //   - Can view doctors (specialist consultations).
        // ------------------------------------------------------------------
        $doctor = Role::firstOrCreate(['name' => 'doctor', 'guard_name' => 'web']);
        $doctor->syncPermissions($this->buildPermissions([
            'Appointment'   => ['ViewAny', 'View', 'Create', 'Update'],
            'MedicalRecord' => ['ViewAny', 'View', 'Create', 'Update'],
            'Patient'       => ['ViewAny', 'View', 'Create', 'Update'],
            'Doctor'        => ['ViewAny', 'View'],
        ]));

        // ------------------------------------------------------------------
        // Role: receptionist — schedule management and patient registration.
        //   - Full appointment management.
        //   - Can only view/create patients (no edit or delete).
        //   - No access to medical records, workspaces, or roles.
        // ------------------------------------------------------------------
        $receptionist = Role::firstOrCreate(['name' => 'receptionist', 'guard_name' => 'web']);
        $receptionist->syncPermissions($this->buildPermissions([
            'Appointment' => ['ViewAny', 'View', 'Create', 'Update', 'Delete', 'DeleteAny'],
            'Patient'     => ['ViewAny', 'View', 'Create'],
            'Doctor'      => ['ViewAny', 'View'],
        ]));

        // ------------------------------------------------------------------
        // Role: user — panel access with no resource permissions.
        //   Equivalent to Shield's panel_user.
        // ------------------------------------------------------------------
        $user = Role::firstOrCreate(['name' => 'user', 'guard_name' => 'web']);
        $user->syncPermissions([]);

        // ------------------------------------------------------------------
        // Role: panel_user — Shield base role (panel accessible, no resources).
        // ------------------------------------------------------------------
        $panelUser = Role::firstOrCreate(['name' => 'panel_user', 'guard_name' => 'web']);
        $panelUser->syncPermissions([]);

        // ------------------------------------------------------------------
        // Role: platform_admin — SaaS owner. Gates the separate /superadmin
        // Filament panel (User::canAccessPanel). Given every permission so the
        // owner can also enter the clinical /admin panel if needed.
        // ------------------------------------------------------------------
        $platformAdmin = Role::firstOrCreate(['name' => 'platform_admin', 'guard_name' => 'web']);
        $platformAdmin->syncPermissions($allPermissions);

        // ------------------------------------------------------------------
        // The SaaS owner (Mathias) gets platform_admin (for /superadmin) and
        // super_admin (for the clinical /admin panel). The demo clinic accounts
        // stay role-less in Filament — they use the React app, not the panels.
        // ------------------------------------------------------------------
        $owner = User::where('email', 'owner@example.com')->first();
        if ($owner) {
            $owner->syncRoles(['platform_admin', 'super_admin']);
        }

        $this->command->info('Shield roles and permissions created successfully.');
        $this->command->table(
            ['Role', 'Permissions assigned'],
            [
                ['super_admin', count($allPermissions) . ' (all)'],
                ['admin', count($allPermissions) . ' (all)'],
                ['doctor', count($doctor->permissions)],
                ['receptionist', count($receptionist->permissions)],
                ['user', '0 (panel only)'],
                ['panel_user', '0 (Shield base role)'],
            ]
        );
    }

    /**
     * Builds the permission names array in {Action}:{Model} format
     * from a compact entity => [actions] map.
     *
     * @param  array<string, string[]>  $map
     * @return string[]
     */
    private function buildPermissions(array $map): array
    {
        $permissions = [];
        foreach ($map as $model => $actions) {
            foreach ($actions as $action) {
                $permissions[] = "{$action}:{$model}";
            }
        }

        return $permissions;
    }
}
